46	int64_t GetElementStorageBits(DataType dtype) {
47	  // Layout aliasing must be reasoned about in logical storage bits per element,
48	  // not in bytes.  For sub-byte dtypes such as fp4, `dtype.bytes()` rounds up
49	  // to 1 and loses the "two fp4 values share one byte" relationship that
50	  // subtype-changing views rely on.
51	  return static_cast<int64_t>(dtype.bits()) * dtype.lanes();
52	}
53	
54	bool ShapesEqual(const Array<PrimExpr> &lhs, const Array<PrimExpr> &rhs,
55	                 arith::Analyzer *analyzer) {
56	  if (lhs.size() != rhs.size()) {
57	    return false;
58	  }
59	  for (size_t i = 0; i < lhs.size(); ++i) {
60	    if (!analyzer->CanProveEqual(lhs[i], rhs[i])) {
61	      return false;
62	    }
63	  }
64	  return true;
65	}
66	
67	Optional<Buffer> FindLayoutAnchorBuffer(const Array<Buffer> &buffers,
68	                                        const Layout &layout,
69	                                        arith::Analyzer *analyzer) {
70	  for (const auto &buffer : buffers) {
71	    if (ShapesEqual(layout->InputShape(), buffer->shape, analyzer)) {
72	      return buffer;
73	    }
74	  }
75	  return Optional<Buffer>();
76	}
