91	class BufferUseDefCollector : public IRVisitorWithAnalyzer {
92	public:
93	  BufferUseDefCollector() = default;
94	
95	  using arith::IRVisitorWithAnalyzer::IRVisitorWithAnalyzer;
96	
97	  void RunInferStep(int cur_infer_id, InferLevel level, bool update_queue,
98	                    LayoutMap &layout_map, const LayoutMap &strict_layout_map,
99	                    std::deque<int> &q, std::vector<bool> &in_queue) {
100	    auto num_infer = infer_list_.size();
101	
102	    // Range check for cur_infer_id
103	    ICHECK_GE(cur_infer_id, 0) << "cur_infer_id is negative, which is invalid.";
104	    ICHECK_LT(cur_infer_id, num_infer)
105	        << "cur_infer_id " << cur_infer_id << " is out of range, must be < "
106	        << num_infer << ".";
107	
108	    // Make sure we can safely access infer_list_[cur_infer_id] and
109	    // thread_index_vec_[cur_infer_id]
110	    auto &next = infer_list_[cur_infer_id];
111	    auto thread_index = thread_index_vec_[cur_infer_id];
112	    auto thread_bounds = thread_bounds_vec_[cur_infer_id];
113	    arith::Analyzer *cur_analyzer = analyzer_vec_[cur_infer_id].get();
114	    // Double-check that 'next' is valid
115	    ICHECK(next.defined()) << "infer_list_[" << cur_infer_id
116	                           << "] is null inside run_infer_step.";
117	
118	    // Check the logical thread index and the thread bounds extent.
119	    ICHECK(thread_index.defined())
120	        << "thread_index_vec_[" << cur_infer_id << "] is not defined.";
121	    ICHECK(thread_bounds.defined())
122	        << "thread_bounds_vec_[" << cur_infer_id << "] is not defined.";
123	
124	    const int64_t *extent_ptr = as_const_int(thread_bounds->extent);
125	    ICHECK(extent_ptr != nullptr)
126	        << "thread_bounds->extent is not a constant integer, which is "
127	           "required for layout inference.";
128	
129	    // Run InferLayout
130	    auto updates = next->InferLayout(LayoutInferArgs{target_,
131	                                                     thread_bounds,
132	                                                     layout_map,
133	                                                     cur_analyzer,
134	                                                     {},
135	                                                     bind_var_to_expr_,
136	                                                     false},
137	                                     level);
138	
139	    // Process the returned updates
140	    for (const auto &[buffer, layout] : updates) {
141	      // Basic validity checks
142	      ICHECK(buffer.defined()) << "InferLayout returned an undefined buffer.";
143	      ICHECK(layout.defined()) << "InferLayout returned an undefined layout.";
144	
145	      // Helper: propagate inferred layout to alias buffers (same data Var)
146	      auto propagate_alias = [&](const Buffer &src_buffer,
147	                                 const Layout &src_layout) {
148	        if (!buffer_data_to_buffers_.count(src_buffer->data))
149	          return;
150	        const auto &siblings = buffer_data_to_buffers_[src_buffer->data];
151	        for (const auto &sib : siblings) {
152	          if (sib.same_as(src_buffer))
153	            continue;
154	          bool shapes_equal =
155	              src_layout->InputShape().size() == sib->shape.size();
156	          if (shapes_equal) {
157	            for (size_t i = 0; i < src_layout->InputShape().size(); ++i) {
158	              if (!analyzer_.CanProveEqual(src_layout->InputShape()[i],
159	                                           sib->shape[i])) {
160	                shapes_equal = false;
161	                break;
162	              }
163	            }
164	          }
165	          Layout target_layout =
166	              shapes_equal
167	                  ? src_layout
168	                  // Alias buffers may reinterpret the same storage with a
169	                  // different element width.  Reshape the inferred layout using
170	                  // the old/new storage bit ratio so that layout inference
171	                  // keeps the physical storage footprint unchanged while
172	                  // allowing the logical element count to change.
173	                  : src_layout->Reshape(
174	                        sib->shape, &analyzer_,
175	                        Integer(GetElementStorageBits(src_buffer->dtype)),
176	                        Integer(GetElementStorageBits(sib->dtype)));
177	          if (layout_map.count(sib)) {
178	            ICHECK(target_layout->IsEqual(layout_map[sib].get()))
179	                << "Get different layout for alias buffer " << sib
180	                << " (data-shared with " << src_buffer
181	                << ")\n current: " << target_layout->DebugOutput()
182	                << "\n previous: " << layout_map[sib]->DebugOutput();
183	          } else {
184	            layout_map.Set(sib, target_layout);
185	            if (update_queue && use_list_.count(sib)) {
186	              for (int idx : use_list_[sib]) {
187	                EnqueueWithPriority(idx, q, in_queue, cur_infer_id, layout_map);
188	              }
189	            }
190	          }
191	        }
192	      };
193	
194	      if (layout_map.count(buffer)) {
195	        // If new layout contains the old one, update map
196	        if (IsFragmentBuffer(buffer) && level != InferLevel::kStrict &&
197	            !strict_layout_map.count(buffer)) {
198	          // Actually this test has been done in ParallelOp::InferLayout
199	          // already. Just do it again to avoid missing implementations in other
200	          // `TileOperator`s.
201	
202	          auto dst_layout_opt = layout.as<Fragment>();
203	          ICHECK(dst_layout_opt.has_value())
204	              << "Failed to cast layout to Fragment for buffer " << buffer
205	              << ", layout type is " << layout->GetTypeKey();
206	          const auto &dst_layout = dst_layout_opt.value();
207	          auto src_layout_opt = layout_map[buffer].as<Fragment>();
208	          ICHECK(src_layout_opt.has_value())
209	              << "Failed to cast layout_map[buffer] to Fragment for buffer "
210	              << buffer << ", layout type is "
211	              << layout_map[buffer]->GetTypeKey();
212	          const auto &src_layout = src_layout_opt.value();
213	          ICHECK(dst_layout->InputDim() == src_layout->InputDim());
214	          Array<PrimExpr> indices;
215	          indices.reserve(dst_layout->InputDim());
216	          arith::Analyzer inner_analyzer;
217	          for (int i = 0; i < dst_layout->InputDim(); ++i) {
218	            auto x = InputPlaceholder(i);
219	            indices.push_back(x);
220	            // should be literal - literal = 0, any analyzer will work
221	            ICHECK(is_zero(inner_analyzer.Simplify(
222	                dst_layout->InputShape()[i] - src_layout->InputShape()[i])));
223	            inner_analyzer.Bind(x, Range(0, dst_layout->InputShape()[i]));
224	          }
225	          if (ProveFragmentContains(src_layout, dst_layout, indices, indices,
226	                                    inner_analyzer)) {
227	            layout_map.Set(buffer, layout);
228	            // Propagate to alias buffers as well
229	            propagate_alias(buffer, layout);
230	            continue;
231	          }
232	        }
233	
234	        // If already in map, check if they are structurally equal
235	        if (!layout->IsEqual(layout_map[buffer].get())) {
236	          // Try to merge swizzle layouts if both are swizzle layouts
237	          const Layout &existing = layout_map[buffer];
238	          if (!layout.as<Fragment>() && !existing.as<Fragment>()) {
239	            if (auto merged = MergeSwizzleLayouts(existing, layout, buffer)) {
240	              DLOG(WARNING) << "Swizzle layout conflict for buffer " << buffer
241	                            << ", merging to smaller granularity";
242	              layout_map.Set(buffer, merged.value());
243	              propagate_alias(buffer, merged.value());
244	              continue;
245	            }
246	          }
247	          // If not swizzle layouts or merge failed, raise error
248	          LOG(FATAL) << "Get different layout for " << buffer
249	                     << "\n current layout: " << layout->DebugOutput()
250	                     << "\n previous layout: "
251	                     << layout_map[buffer]->DebugOutput();
252	        }
253	        // Ensure aliases are consistent too
254	        propagate_alias(buffer, layout);
255	      } else {
256	        // Otherwise, update map
257	        layout_map.Set(buffer, layout);
258	        // Propagate to alias buffers (may enqueue their users)
259	        propagate_alias(buffer, layout);
260	        if (!update_queue)
261	          continue;
262	
263	        // Check if buffer exists in use_list_
264	        if (!use_list_.count(buffer) && IsFragmentBuffer(buffer)) {
265	          LOG(WARNING) << "Layout inference failed for buffer " << buffer
266	                       << ". "
267	                       << "The buffer cannot be inferred with current layout "
268	                          "inference rules.";
269	          continue;
270	        }
271	
272	        // Push back into BFS queue
273	        for (int idx : use_list_[buffer]) {
274	          ICHECK_GE(idx, 0)
275	              << "Index in use_list_ for buffer " << buffer << " is negative.";
276	          ICHECK_LT(idx, num_infer)
277	              << "Index in use_list_ for buffer " << buffer
278	              << " out of range: " << idx << " >= " << num_infer << ".";
279	
280	          EnqueueWithPriority(idx, q, in_queue, cur_infer_id, layout_map);
281	        }
282	      }
283	    }
284	  };
285	
286	  void FinishInferQueue(InferLevel level, LayoutMap &layout_map,
287	                        const LayoutMap &strict_layout_map, std::deque<int> &q,
288	                        std::vector<bool> &in_queue) {
289	    auto num_infer = infer_list_.size();
290	
291	    while (!q.empty()) {
292	      int cur_infer_id = q.front();
293	      q.pop_front();
294	      // Range check again, just to be safe
295	      ICHECK_GE(cur_infer_id, 0);
296	      ICHECK_LT(cur_infer_id, num_infer);
297	
298	      in_queue[cur_infer_id] = false;
299	      RunInferStep(cur_infer_id, level, true, layout_map, strict_layout_map, q,
300	                   in_queue);
301	    }
302	  };
303	
304	  LayoutInferenceResult Run() {
305	    // Basic consistency check: infer_list_ and thread_index_vec_ should have
306	    // the same size
307	    ICHECK_EQ(infer_list_.size(), thread_index_vec_.size())
308	        << "Size mismatch: infer_list_ and thread_index_vec_ must match in "
309	           "length.";
310	    ICHECK_EQ(thread_bounds_vec_.size(), infer_list_.size())
311	        << "Size mismatch: thread_bounds_vec_ and infer_list_ must match in "
312	           "length.";
313	    ICHECK_EQ(analyzer_vec_.size(), infer_list_.size())
314	        << "Size mismatch: analyzer_vec_ and infer_list_ must match in "
315	           "length.";
316	    DLOG(INFO) << "[InferLayout] all participating operators:" << '\n';
317	    for (int i = 0; i < infer_list_stmt_.size(); ++i) {
318	      DLOG(INFO) << "    op " << i << ":" << infer_list_stmt_[i] << '\n';
319	    }
320	
321	    // If needed, you can also check that annotated_layout_map_ is not empty, or
322	    // anything else relevant to your setup.
323	
324	    // Copy the annotated layout map to local variable
325	    Map<Buffer, Layout> layout_map = annotated_layout_map_;
326	    Map<Buffer, Layout> strict_layout_map;
327	    int num_infer = infer_list_.size();
328	
329	    // Prepare BFS queue for iterative inference
330	    std::deque<int> q;
331	    std::vector<bool> in_queue(num_infer, true);
332	    for (int i = 0; i < num_infer; i++) {
333	      // Check that each infer_list_ entry is valid
334	      ICHECK(infer_list_[i].defined())
335	          << "infer_list_[" << i
336	          << "] is null. The inference object is not allocated properly.";
337	      q.push_back(i);
338	    }
339	
340	    // step 0: set fully replicated layout for floating fragment buffers
341	    // Floating buffers are accessed outside TileOps (e.g., in if conditions),
342	    // so they must be replicated across all threads.
343	    for (const auto &[buffer, thread_bounds] : floating_fragment_buffers_) {
344	      if (layout_map.count(buffer))
345	        continue;
346	      auto frag =
347	          Fragment::FullyReplicated(buffer->shape, thread_bounds->extent)
348	              ->BindThreadRange(thread_bounds);
349	      layout_map.Set(buffer, frag);
350	    }
351	
352	    // step 1: infer strict layout
353	    for (int i = 0; i < num_infer; i++) {
354	      RunInferStep(i, InferLevel::kStrict, false, layout_map, strict_layout_map,
355	                   q, in_queue);
356	    }
357	
358	    for (const auto &[buffer, layout] : layout_map) {
359	      strict_layout_map.Set(buffer, layout);
360	    }
361	
362	    // step 2: infer common layout with BFS
363	    FinishInferQueue(InferLevel::kCommon, layout_map, strict_layout_map, q,
364	                     in_queue);
365	    // step 3: relax constraints to free and re-run
366	    InferInFreeMode(layout_map, strict_layout_map);
367	    // step 4: finalize alias layouts by Var
368	    // For each storage var, if any buffer in the group has a layout,
369	    // propagate (reshape if needed) to the rest to ensure completeness.
370	    for (const auto &[var, buffers] : buffer_data_to_buffers_) {
371	      // Find a representative with existing layout
372	      Optional<Buffer> rep;
373	      Optional<Layout> rep_layout;
374	      for (const auto &buf : buffers) {
375	        if (layout_map.count(buf)) {
376	          rep = buf;
377	          rep_layout = layout_map[buf];
378	          break;
379	        }
380	      }
381	      if (!rep_layout.defined())
382	        continue;
383	      for (const auto &buf : buffers) {
384	        if (!layout_map.count(buf)) {
385	          bool shapes_equal =
386	              rep_layout.value()->InputShape().size() == buf->shape.size();
387	          if (shapes_equal) {
388	            for (size_t i = 0; i < rep_layout.value()->InputShape().size();
389	                 ++i) {
390	              if (!analyzer_.CanProveEqual(rep_layout.value()->InputShape()[i],
391	                                           buf->shape[i])) {
392	                shapes_equal = false;
393	                break;
394	              }
395	            }
396	          }
397	          Layout reshaped =
398	              shapes_equal
399	                  ? rep_layout.value()
400	                  : rep_layout.value()->Reshape(
401	                        buf->shape, &analyzer_,
402	                        Integer(GetElementStorageBits(rep.value()->dtype)),
403	                        Integer(GetElementStorageBits(buf->dtype)));
404	          layout_map.Set(buf, reshaped);
405	        }
406	      }
407	    }
408	
409	    // Check that all local.fragment buffers have inferred layouts
410	    for (const auto &[buffer, _] : use_list_) {
411	      if (IsFragmentBuffer(buffer)) {
412	        ICHECK_NE(layout_map.count(buffer), 0)
413	            << "The layout for fragment " << buffer
414	            << " can not be inferred correctly.";
415	      }
416	    }
417	
418	    // Collect layout info for For nodes
419	    Map<For, Fragment> for_map;
420	    Map<For, PrimExpr> predicate_map;
421	    Map<For, Bool> padding_guard_map;
422	    ICHECK(infer_list_.size() == thread_index_vec_.size())
423	        << "infer_list_ and thread_index_vec_ size mismatch";
424	    for (int i = 0; i < infer_list_.size(); i++) {
425	      TileOperator base_infer = std::move(infer_list_[i]);
426	      auto thread_index = thread_index_vec_[i];
427	
428	      // Check if base_infer is valid
429	      ICHECK(base_infer.defined()) << "Null pointer encountered in "
430	                                      "infer_list_ while collecting for_map.";
431	      if (auto for_infer = base_infer.as<ParallelOpNode>()) {
432	        // Check that the loop layout is defined
433	        ICHECK(for_infer->GetLoopLayout().defined())
434	            << "The Layout for Parallel for cannot be inferred correctly:\n"
435	            << for_infer->GetRoot();
436	        for_map.Set(for_infer->GetRoot(), for_infer->GetLoopLayout());
437	        if (for_infer->LoopLayoutRequiresPaddingGuard()) {
438	          padding_guard_map.Set(for_infer->GetRoot(), Bool(true));
439	        }
440	        // thread_index should be defined if we rely on it
441	        ICHECK(thread_index.defined())
442	            << "thread_index is not defined. Cannot retrieve predicate.";
443	
444	        if (auto predicate = for_infer->GetPredicate(thread_index)) {
445	          predicate_map.Set(for_infer->GetRoot(), predicate.value());
446	        }
447	      }
448	    }
449	
450	    return {layout_map, for_map, predicate_map, padding_guard_map};
451	  }
452	
453	  void Collect(const PrimFunc &f) {
454	    for (const auto &[_, buffer] : f->buffer_map) {
455	      if (buffer_data_to_buffers_.count(buffer->data)) {
456	        auto buffers = buffer_data_to_buffers_[buffer->data];
457	        buffers.push_back(buffer);
458	        buffer_data_to_buffers_.Set(buffer->data, buffers);
459	      } else {
460	        buffer_data_to_buffers_.Set(buffer->data, {buffer});
461	      }
462	    }
463	    auto target = f->GetAttr<Target>(tvm::attr::kTarget);
464	    ICHECK(target.defined())
465	        << "Layout_Inference: Require the target attribute";
466	    target_ = target.value();
467	    this->operator()(f->body);
468	    // Compute floating fragment buffers after collection
469	    ComputeFloatingFragmentBuffers(f->body);
470	  }
