472	private:
473	  Map<Var, Buffer> GetBufferMap() const {
474	    Map<Var, Buffer> buffer_map;
475	    for (const auto &[var, buffers] : buffer_data_to_buffers_) {
476	      // Use the first buffer for each var
477	      // TODO(lei): phaseout buffer_map in future.
478	      if (!buffers.empty()) {
479	        buffer_map.Set(var, buffers[0]);
480	      }
481	    }
482	    return buffer_map;
483	  }
484	
485	  // Return true if any buffer that this op (idx) touches already has
486	  // an inferred layout in layout_map. Used to prioritize enqueue order.
487	  bool HasKnownLayoutAnchor(int idx, const LayoutMap &layout_map) const {
488	    auto it = op_touched_buffers_.find(idx);
489	    if (it == op_touched_buffers_.end() || it->second.empty())
490	      return false;
491	    for (const auto &buf : it->second) {
492	      if (layout_map.count(buf))
493	        return true;
494	    }
495	    return false;
496	  }
497	
498	  // Enqueue idx to q with priority if all its buffers already
499	  // have layouts. Also guards against duplicates and self-enqueue.
500	  void EnqueueWithPriority(int idx, std::deque<int> &q,
501	                           std::vector<bool> &in_queue, int cur_infer_id,
502	                           const LayoutMap &layout_map) const {
503	    if (idx == cur_infer_id)
504	      return;
505	    if (idx < 0 || idx >= static_cast<int>(in_queue.size()))
506	      return;
507	    if (in_queue[idx])
508	      return;
509	    in_queue[idx] = true;
510	    if (HasKnownLayoutAnchor(idx, layout_map)) {
511	      q.push_front(idx);
512	    } else {
513	      q.push_back(idx);
514	    }
515	  }
516	
517	  void VisitExpr_(const CallNode *op) final {
518	    IRVisitorWithAnalyzer::VisitExpr_(op);
519	    // Do not analysis the call node to the global function.
520	    if (op->op.as<GlobalVarNode>())
521	      return;
522	
523	    auto p = ParseOperator(GetRef<Call>(op));
524	    if (p.defined()) {
525	      for (const auto &arg : op->args) {
526	        if (auto buffer = getBufferFromAccessPtr(arg)) {
527	          addToUseList(buffer.value());
528	        } else if (auto buffer = getBufferFromRegion(arg)) {
529	          addToUseList(buffer.value());
530	        }
531	        // Check if the argument uses any Bind variables that reference
532	        // fragment buffers. If so, add those buffers to the use list.
533	        // This handles cases like: a = block_mask_f[i]; T.copy(A[a, 0], ...)
534	        CollectFragmentBuffersFromExpr(arg);
535	      }
536	      // Compute thread_index and thread_bounds
537	      thread_index_vec_.push_back(CurrentThreadIndex());
538	      thread_bounds_vec_.push_back(CurrentThreadBounds());
539	      analyzer_vec_.push_back(analyzer_.Clone());
540	
541	      // Add the tile operator to infer_list_
542	      infer_list_stmt_.push_back(GetRef<ObjectRef>(op));
543	      infer_list_.push_back(std::move(p));
544	    }
545	  }
546	
547	  Optional<Buffer> getBufferFromAccessPtr(const PrimExpr &expr) {
548	    if (auto bl = expr.as<BufferLoadNode>()) {
549	      return bl->buffer;
550	    }
551	    auto call = expr.as<CallNode>();
552	    if (!call) {
553	      return std::nullopt;
554	    }
555	    if (call->op.same_as(builtin::tvm_access_ptr())) {
556	      auto var_opt = call->args[1].as<Var>();
557	      if (!var_opt.has_value()) {
558	        LOG(WARNING) << "[getBufferFromAccessPtr] args[1] is not a Var, type: "
559	                     << call->args[1]->GetTypeKey();
560	        return std::nullopt;
561	      }
562	      const auto &var = var_opt.value();
563	      if (buffer_data_to_buffers_.count(var)) {
564	        const auto &buffers = buffer_data_to_buffers_[var];
565	        if (!buffers.empty()) {
566	          return buffers[0]; // Return the first buffer
567	        }
568	      }
569	      return std::nullopt;
570	    }
571	    return std::nullopt;
572	  }
573	
574	  Optional<Buffer> getBufferFromRegion(const PrimExpr &expr) {
575	    if (auto call = expr.as<CallNode>()) {
576	      if (call->op.same_as(RegionOp::Get())) {
577	        if (auto bl = call->args[0].as<BufferLoadNode>()) {
578	          return bl->buffer;
579	        }
580	        return std::nullopt;
581	      }
582	    }
583	    return std::nullopt;
584	  }
