586	  void addToUseList(const Buffer &buffer) {
587	    // buffer scope must be local.fragment
588	    if (!IsFragmentBuffer(buffer)) {
589	      return;
590	    }
591	    int infer_idx = infer_list_.size();
592	    if (use_list_.find(buffer) == use_list_.end()) {
593	      use_list_[buffer] = {};
594	    }
595	    use_list_[buffer].push_back(infer_idx);
596	
597	    // Track which buffers this op (infer_idx) touches for prioritization.
598	    // Avoid duplicates.
599	    auto &vec = op_touched_buffers_[infer_idx];
600	    if (std::none_of(vec.begin(), vec.end(),
601	                     [&](const Buffer &b) { return b.same_as(buffer); })) {
602	      vec.push_back(buffer);
603	    }
604	  }
605	
606	  void VisitStmt_(const ForNode *op) final {
607	    if (op->kind == ForKind::kParallel) {
608	      auto infer = ParallelOp(GetRef<For>(op));
609	      for (const auto &buffer : infer->GetAccessOrder()) {
610	        addToUseList(buffer);
611	      }
612	
613	      PostOrderVisit(op->body, [this](const ObjectRef &node) {
614	        if (auto *buffer_load = node.as<BufferLoadNode>()) {
615	          if (buffer_load->buffer.defined() &&
616	              buffer_load->buffer->data.defined()) {
617	            if (buffer_data_to_buffers_.count(buffer_load->buffer->data)) {
618	              // Check if this buffer is already in the list
619	              auto buffers = buffer_data_to_buffers_[buffer_load->buffer->data];
620	              bool found = false;
621	              for (const auto &buf : buffers) {
622	                if (buf.same_as(buffer_load->buffer)) {
623	                  found = true;
624	                  break;
625	                }
626	              }
627	              if (!found) {
628	                buffers.push_back(buffer_load->buffer);
629	                buffer_data_to_buffers_.Set(buffer_load->buffer->data, buffers);
630	                DLOG(INFO) << "[LayoutInference] BufferStore: added buffer "
631	                           << buffer_load->buffer
632	                           << " buffer.get() = " << buffer_load->buffer.get()
633	                           << " data = " << buffer_load->buffer->data.get();
634	              }
635	            } else {
636	              buffer_data_to_buffers_.Set(buffer_load->buffer->data,
637	                                          {buffer_load->buffer});
638	              DLOG(INFO) << "[LayoutInference] BufferStore: new buffer "
639	                         << buffer_load->buffer
640	                         << " buffer.get() = " << buffer_load->buffer.get()
641	                         << " data = " << buffer_load->buffer->data.get();
642	            }
643	          }
644	        } else if (auto *buffer_store = node.as<BufferStoreNode>()) {
645	          if (buffer_store->buffer.defined() &&
646	              buffer_store->buffer->data.defined()) {
647	            if (buffer_data_to_buffers_.count(buffer_store->buffer->data)) {
648	              auto buffers =
649	                  buffer_data_to_buffers_[buffer_store->buffer->data];
650	              bool found = false;
651	              for (const auto &buf : buffers) {
652	                if (buf.same_as(buffer_store->buffer)) {
653	                  found = true;
654	                  break;
655	                }
656	              }
657	              if (!found) {
658	                buffers.push_back(buffer_store->buffer);
659	                buffer_data_to_buffers_.Set(buffer_store->buffer->data,
660	                                            buffers);
661	                DLOG(INFO) << "[LayoutInference] BufferStore: added buffer "
662	                           << buffer_store->buffer
663	                           << " buffer.get() = " << buffer_store->buffer.get()
664	                           << " data = " << buffer_store->buffer->data.get();
665	              }
666	            } else {
667	              buffer_data_to_buffers_.Set(buffer_store->buffer->data,
668	                                          {buffer_store->buffer});
669	              DLOG(INFO) << "[LayoutInference] BufferStore: new buffer "
670	                         << buffer_store->buffer
671	                         << " buffer.get() = " << buffer_store->buffer.get()
672	                         << " data = " << buffer_store->buffer->data.get();
673	            }
674	          }
675	        }
676	      });
677	      infer_list_stmt_.push_back(GetRef<ObjectRef>(op));
678	      infer_list_.push_back(std::move(infer));
679	      thread_index_vec_.push_back(CurrentThreadIndex());
680	      thread_bounds_vec_.push_back(CurrentThreadBounds());
681	      analyzer_vec_.push_back(analyzer_.Clone());
682	    } else {
683	      IRVisitorWithAnalyzer::VisitStmt(op->body);
684	    }
685	  }
