687	  void VisitStmt_(const SBlockNode *op) final {
688	    for (auto buffer : op->alloc_buffers) {
689	      if (buffer_data_to_buffers_.count(buffer->data)) {
690	        auto buffers = buffer_data_to_buffers_[buffer->data];
691	        buffers.push_back(buffer);
692	        buffer_data_to_buffers_.Set(buffer->data, buffers);
693	      } else {
694	        buffer_data_to_buffers_.Set(buffer->data, {buffer});
695	      }
696	    }
697	
698	    // First, visit the block body to collect all buffers from
699	    // BufferLoad/BufferStore
700	    IRVisitorWithAnalyzer::VisitStmt_(op);
701	
702	    // After visiting, apply layouts to all collected buffers
703	    if (op->annotations.count(attr::kLayoutMap)) {
704	      // Check if the layout map is Map<Var, Layout>
705	      auto map =
706	          op->annotations.Get(attr::kLayoutMap)->as<Map<Var, Layout>>().value();
707	      for (const auto &[var, layout] : map) {
708	        ICHECK(buffer_data_to_buffers_.count(var))
709	            << "buffer " << var << " is not found in the block";
710	        const auto &buffers = buffer_data_to_buffers_[var];
711	        ICHECK(!buffers.empty()) << "buffer list for " << var << " is empty";
712	        Optional<Buffer> anchor_buffer =
713	            FindLayoutAnchorBuffer(buffers, layout, &analyzer_);
714	        int64_t anchor_bits =
715	            anchor_buffer.defined()
716	                ? GetElementStorageBits(anchor_buffer.value()->dtype)
717	                : GetElementStorageBits(buffers[0]->dtype);
718	        // Apply layout to all buffers associated with this var
719	        for (const auto &buffer : buffers) {
720	
721	          // Reshape the layout to match the buffer's shape
722	          // Check if shapes are structurally equal
723	          bool shapes_equal =
724	              ShapesEqual(layout->InputShape(), buffer->shape, &analyzer_);
725	
726	          Layout resolved_layout =
727	              shapes_equal
728	                  ? layout
729	                  : layout->Reshape(
730	                        buffer->shape, &analyzer_, Integer(anchor_bits),
731	                        Integer(GetElementStorageBits(buffer->dtype)));
732	          if (IsSharedBuffer(buffer)) {
733	            arith::IterMapResult injectivity =
734	                resolved_layout->DetectInjective();
735	            if (!injectivity->errors.empty()) {
736	              TVM_FFI_THROW(ValueError)
737	                  << "Invalid layout for shared buffer `" << buffer->name
738	                  << "`: the forward map must be injective. Details: "
739	                  << injectivity->errors
740	                  << ". Layout: " << resolved_layout->DebugOutput()
741	                  << ". Check the layout passed to T.annotate_layout.";
742	            }
743	          }
744	          annotated_layout_map_.Set(buffer, resolved_layout);
745	        }
746	      }
747	    }
748	  }
