769	  // following Bind value chains.
770	  void CollectFragmentBuffersFromExpr(const PrimExpr &expr) {
771	    PostOrderVisit(expr, [this](const ObjectRef &node) {
772	      if (auto bl = node.as<BufferLoadNode>()) {
773	        if (IsFragmentBuffer(bl->buffer)) {
774	          addToUseList(bl->buffer);
