859	  // Compute floating fragment buffers after collection is done.
860	  //
861	  // A "floating" fragment buffer is one that has accesses outside of any
862	  // TileOp (Copy, Gemm, Reduce, Parallel, etc.). For example:
863	  //
864	  //   T.copy(BlockMask[by, :], block_mask_f)  // block_mask_f accessed IN
865	  //   TileOp for i in T.Pipelined(N_S):
866	  //       if block_mask_f[i] >= 0:           // block_mask_f accessed OUTSIDE
867	  //       TileOp (floating!)
868	  //           T.copy(A[...], A_shared)
869	  //
870	  // In this example, `block_mask_f[i]` in the if-condition is a "floating"
871	  // access because it's not inside any TileOp. Such buffers need special
872	  // handling: they must be fully replicated across all threads since the
873	  // access pattern cannot be inferred from TileOp semantics.
874	  //
875	  // This function identifies these buffers by:
876	  // 1. Collecting all IR nodes that are inside TileOps (from infer_list_stmt_)
877	  // 2. Scanning the entire function body for fragment buffer accesses
878	  // 3. Any access not inside a TileOp means the buffer is "floating"
879	  // 4. Recording the thread_bounds at the point of each floating access
880	  void ComputeFloatingFragmentBuffers(const Stmt &func_body) {
881	    // Step 1: Collect all nodes that are inside TileOps
882	    std::unordered_set<const Object *> nodes_in_tileops;
883	    for (const auto &stmt : infer_list_stmt_) {
884	      PostOrderVisit(stmt, [&](const ObjectRef &node) {
885	        nodes_in_tileops.insert(node.get());
886	      });
887	    }
888	
889	    // Step 2: Use a visitor to scan for floating accesses while tracking thread
890	    // context
891	    class FloatingBufferCollector : public IRVisitorWithAnalyzer {
892	    public:
893	      FloatingBufferCollector(
894	          const std::unordered_set<const Object *> &nodes_in_tileops,
895	          std::unordered_map<Buffer, Range, ObjectPtrHash, ObjectPtrEqual>
896	              &floating_buffers)
897	          : nodes_in_tileops_(nodes_in_tileops),
898	            floating_buffers_(floating_buffers) {}
899	
900	      void VisitStmt_(const AttrStmtNode *op) final {
901	        if (op->attr_key == tirx::attr::thread_extent) {
902	          IterVar iv = Downcast<IterVar>(op->node);
903	          if (iv->thread_tag == "threadIdx.x") {
904	            thread_var_ = iv;
905	          }
906	        }
907	        IRVisitorWithAnalyzer::VisitStmt_(op);
908	      }
909	
910	      void VisitExpr_(const BufferLoadNode *op) final {
911	        CheckFloatingAccess(op->buffer, op);
912	        IRVisitorWithAnalyzer::VisitExpr_(op);
913	      }
914	
915	      void VisitStmt_(const BufferStoreNode *op) final {
916	        CheckFloatingAccess(op->buffer, op);
917	        IRVisitorWithAnalyzer::VisitStmt_(op);
918	      }
919	
920	    private:
921	      void CheckFloatingAccess(const Buffer &buffer, const Object *node) {
922	        if (!IsFragmentBuffer(buffer))
923	          return;
924	        if (nodes_in_tileops_.find(node) != nodes_in_tileops_.end())
925	          return;
926	        // This is a floating access - record buffer with current thread_bounds
927	        if (floating_buffers_.find(buffer) != floating_buffers_.end())
928	          return; // Already recorded
929	        floating_buffers_[buffer] = CurrentThreadBounds();
930	      }
931	
932	      Range CurrentThreadBounds() const {
933	        return ComputeThreadBounds(thread_var_, analyzer_);
934	      }
935	
936	      const std::unordered_set<const Object *> &nodes_in_tileops_;
937	      std::unordered_map<Buffer, Range, ObjectPtrHash, ObjectPtrEqual>
938	          &floating_buffers_;
939	      IterVar thread_var_;
940	    };
941	
942	    FloatingBufferCollector collector(nodes_in_tileops,
943	                                      floating_fragment_buffers_);
944	    collector(func_body);
945	
946	    // Debug log floating fragment buffers
947	    if (!floating_fragment_buffers_.empty()) {
948	      DLOG(INFO)
949	          << "Floating fragment buffers (have accesses outside TileOps):";
950	      for (const auto &[buffer, thread_bounds] : floating_fragment_buffers_) {
951	        DLOG(INFO) << "    " << buffer
952	                   << " with thread_bounds: " << thread_bounds;
953	      }
954	    }
955	  }
956	
957	  Map<Var, Array<Buffer>> buffer_data_to_buffers_;
958	  // Map from Bind variable to its bound expression
959	  Map<Var, PrimExpr> bind_var_to_expr_;
960	  std::vector<ObjectRef> infer_list_stmt_;
961	  std::vector<TileOperator> infer_list_;
962	  // Fragment buffers that have accesses outside of TileOps.
963	  // These "floating" buffers need fully replicated layouts since their
964	  // access patterns cannot be inferred from TileOp semantics.
965	  // Maps buffer -> thread_bounds at the point of floating access.
966	  // See ComputeFloatingFragmentBuffers() for detailed explanation.
967	  std::unordered_map<Buffer, Range, ObjectPtrHash, ObjectPtrEqual>
968	      floating_fragment_buffers_;
969	  std::unordered_map<Buffer, std::vector<int>, ObjectPtrHash, ObjectPtrEqual>
970	      use_list_;
971	  // Per-op list of buffers it touches (fragment scope), used for prioritization
972	  std::unordered_map<int, std::vector<Buffer>> op_touched_buffers_;
973	  // Real threadIdx.x binding of the enclosing thread_extent scope, when one
974	  // exists. Stays undefined for targets without thread bindings (e.g. CPU),
975	  // where the logical thread index is the constant 0 and thread bounds are
976	  // [0, 1) — no synthetic fallback Var is ever created.
977	  IterVar thread_binding_;
978	  std::vector<PrimExpr> thread_index_vec_;
979	  std::vector<Range> thread_bounds_vec_;
980	  std::vector<std::unique_ptr<arith::Analyzer>> analyzer_vec_;
981	  Target target_;
982	  LayoutMap annotated_layout_map_;
983	
984	  std::vector<TileOperator> BackupInferList() {
985	    std::vector<TileOperator> back_infer_list;
986	    back_infer_list.reserve(infer_list_.size());
987	    for (auto &&p : infer_list_) {
988	      back_infer_list.push_back(p->Clone());
