992	
993	  void InferInFreeMode(LayoutMap &layout_map,
994	                       const LayoutMap &strict_layout_map) {
995	
996	    DLOG(INFO) << "Enforced layout maps:" << '\n';
997	    for (auto &&[k, v] : layout_map) {
998	      DLOG(INFO) << "    " << k << ": " << v->DebugOutput() << '\n';
999	    }
1000	    DLOG(INFO) << '\n';
1001	
1002	    // Group operators into connected components
1003	    UnionFind<int> uf;
1004	    for (int i = 0; i < infer_list_.size(); i++) {
1005	      uf.MakeSet(i);
1006	    }
1007	    for (const auto &[buffer, infer_indices] : use_list_) {
1008	      if (infer_indices.empty())
1009	        continue;
1010	
1011	      // Union all infer_list_ indices that share the same Buffer object
1012	      int first_idx = infer_indices[0];
1013	      for (size_t i = 1; i < infer_indices.size(); i++) {
1014	        uf.Union(first_idx, infer_indices[i]);
1015	      }
1016	    }
1017	    // Additionally, union across buffers that share the same underlying
1018	    // buffer->data (Var). This handles cases like reshape where multiple
1019	    // Buffer objects alias the same storage.
1020	    for (const auto &[var, buffers] : buffer_data_to_buffers_) {
1021	      std::vector<int> merged;
1022	      for (const auto &buf : buffers) {
1023	        auto it = use_list_.find(buf);
1024	        if (it != use_list_.end()) {
1025	          const auto &vec = it->second;
1026	          merged.insert(merged.end(), vec.begin(), vec.end());
1027	        }
1028	      }
1029	      if (merged.size() > 1) {
1030	        std::sort(merged.begin(), merged.end());
1031	        merged.erase(std::unique(merged.begin(), merged.end()), merged.end());
1032	        int first = merged[0];
1033	        for (size_t i = 1; i < merged.size(); ++i) {
1034	          uf.Union(first, merged[i]);
1035	        }
1036	      }
1037	    }
1038	
1039	    std::unordered_map<int, std::vector<int>> components;
1040	    for (int i = 0; i < infer_list_.size(); i++) {
1041	      int root = uf.Find(i);
1042	      components[root].push_back(i);
1043	    }
1044	    // Create a map from root to buffers
1045	    std::unordered_map<int, std::vector<Buffer>> components_buffers;
1046	    for (const auto &[buffer, infer_indices] : use_list_) {
1047	      int root = uf.Find(infer_indices[0]);
1048	      components_buffers[root].push_back(buffer);
1049	    }
1050	    // Keep components_buffers for debug purpose
1051	    (void)components_buffers;
1052	
1053	    // For each component, try each op as root, and determine the least
1054	    // replicated one
1055	    std::deque<int> q;
1056	    std::vector<bool> in_queue(infer_list_.size(), false);
1057	
1058	    for (auto &&[root, members] : components) {
1059	      DLOG(INFO) << "======================= processing component " << root
1060	                 << '\n';
1061	      decltype(infer_list_) best_infer_list;
1062	      LayoutMap best_layout_map;
1063	      int64_t min_reg_num = INT64_MAX;
1064	      int min_reg_num_infer_root = -1;
1065	
1066	      // Try each member as the root of inference for this component
1067	      for (int attempt_infer_root : members) {
1068	        DLOG(INFO) << "----------------------- try root " << attempt_infer_root
1069	                   << " members " << members.size() << '\n';
1070	        // Backup the current infer_list_ state
1071	        auto back_infer_list = BackupInferList();
1072	        // Copy the current layout_map for temporary use
1073	        LayoutMap tmp_layout_map = layout_map;
1074	        bool do_update = true;
1075	        try {
1076	          // Run inference starting from attempt_infer_root
1077	          RunInferStep(attempt_infer_root, InferLevel::kFree, true,
1078	                       tmp_layout_map, strict_layout_map, q, in_queue);
1079	          FinishInferQueue(InferLevel::kFree, tmp_layout_map, strict_layout_map,
1080	                           q, in_queue);
1081	
1082	          // After the first search, run inference for all other members in
1083	          // order
1084	          for (int other_infer_root : members) {
1085	            if (other_infer_root != attempt_infer_root) {
1086	              RunInferStep(other_infer_root, InferLevel::kFree, true,
1087	                           tmp_layout_map, strict_layout_map, q, in_queue);
1088	              FinishInferQueue(InferLevel::kFree, tmp_layout_map,
1089	                               strict_layout_map, q, in_queue);
1090	            }
1091	          }
1092	        } catch (const LayoutConflictException &e) {
1093	          do_update = false;
1094	          DLOG(INFO) << "attempt failed due to LayoutConflictException "
1095	                     << e.what() << '\n';
1096	        } catch (const NormalizeIterException &e) {
1097	          do_update = false;
1098	          DLOG(INFO) << "attempt failed due to NormalizeIterException "
1099	                     << e.what() << '\n';
1100	        } catch (const LoopLayoutInjectiveException &e) {
1101	          do_update = false;
1102	          DLOG(INFO) << "attempt failed due to LoopLayoutInjectiveException "
1103	                     << e.what() << '\n';
1104	        }
1105	
1106	        if (do_update) {
1107	          // Compute the total register number for this layout
1108	          int64_t reg_num = 0;
1109	          for (const auto &[buffer, layout] : tmp_layout_map) {
1110	            if (auto frag = layout.as<Fragment>()) {
1111	              int64_t frag_reg_num = 1;
1112	              for (auto i : frag.value()->OutputShape()) {
1113	                auto pci = as_const_int(i);
1114	                ICHECK(pci != nullptr)
1115	                    << "Can not use non-constant range to "
1116	                       "iterate over a fragment/local "
1117	                       "buffer. Non-constant shape expr is: "
1118	                    << i
1119	                    << ". This is possibly because you use symbolic shape when "
1120	                       "accessing a fragment/local buffer.";
1121	                frag_reg_num *= *pci;
1122	              }
1123	              reg_num += frag_reg_num;
1124	            }
1125	          }
1126	          // Update the best plan if this one uses fewer registers
1127	          if (reg_num < min_reg_num ||
1128	              (reg_num == min_reg_num &&
1129	               attempt_infer_root < min_reg_num_infer_root)) {
1130	            best_infer_list =
1131	                BackupInferList(); // Use backup to avoid moving out infer_list_
1132	            best_layout_map = tmp_layout_map;
1133	            min_reg_num = reg_num;
1134	            min_reg_num_infer_root = attempt_infer_root;
1135	          }
1136	        }
1137	        // Restore infer_list_ state for the next attempt
1138	        infer_list_ = std::move(back_infer_list);
1139	      }
1140	      ICHECK(min_reg_num < INT64_MAX) << "no available layout found" << '\n';
1141	      // Apply the best plan for this component
1142	      infer_list_ = std::move(best_infer_list);
1143	      layout_map = best_layout_map;
1144	      DLOG(INFO) << "[InferInFreeMode] Final selection is attempt_infer_root = "
1145	                 << min_reg_num_infer_root << '\n';
1146	    }
1147	  }
1148	};
1149	
1150	class LayoutInferencer : public IRMutatorWithAnalyzer {
1151	public:
1152	  static PrimFunc Substitute(PrimFunc f) {
1153	    arith::Analyzer analyzer;
1154	    PrimFuncNode *fptr = f.CopyOnWrite();
1155	    fptr->body = ParallelLoopFuser::Fuse(f->body);
1156	    BufferUseDefCollector collector;
1157	    collector.Collect(f);
1158	    auto result = collector.Run();
1159	    LayoutInferencer substituter(result, &analyzer);
1160	    fptr->body = substituter.VisitStmt(f->body);
1161	    return f;
1162	  }
1163	
1164	private:
1165	  LayoutInferencer(const LayoutInferenceResult &result,
1166	                   arith::Analyzer *analyzer)
1167	      : arith::IRMutatorWithAnalyzer(analyzer), result_(result) {};
1168	
1169	  using arith::IRMutatorWithAnalyzer::IRMutatorWithAnalyzer;
1170	
1171	  /**
1172	   * @brief Visit and mutate a Block node to attach inferred layout information.
1173	   *
1174	   * Converts the visited Block via the base visitor and attaches
1175	   * result_.layout_map to the Block's annotations under attr::kLayoutMap.
1176	   *
1177	   * @return Stmt The (possibly modified) Block statement with the layout-map
1178	   * annotation set.
1179	   */
1180	  Stmt VisitStmt_(const SBlockNode *op) final {
1181	    SBlock block = Downcast<SBlock>(IRMutatorWithAnalyzer::VisitStmt_(op));
1182	
1183	    auto block_ptr = block.CopyOnWrite();
1184	    block_ptr->annotations.Set(attr::kLayoutMap, result_.layout_map);
1185	    return block;
1186	  }
1187	
1188	  /**
1189	   * @brief Visit and transform For nodes by storing inferred layout information
1190	   *        as annotations instead of expanding the loop.
1191	   *
1192	   * If the For node is present in result_.for_map, this method stores the
1193	   * inferred loop layout and predicate as annotations on the For node, rather
1194	   * than performing loop partition and vectorization.
1195	   *
1196	   * The stored annotations are:
1197	   * - attr::kParallelLoopLayout: The Fragment layout for the parallel loop
1198	   * - attr::kParallelLoopPredicate: The predicate expression (if any)
1199	   * - attr::kParallelLoopRequiresPaddingGuard: Whether inverse lowering must
1200	   *   allow and guard padded points from a ragged SIMT partition
1201	   *
1202	   * @return The For statement with layout annotations attached
1203	   */
1204	  Stmt VisitStmt_(const ForNode *op) final {
1205	    if (!result_.for_map.count(GetRef<For>(op))) {
1206	      return IRMutatorWithAnalyzer::VisitStmt_(op);
1207	    }
1208	
1209	    For for_node = Downcast<For>(IRMutatorWithAnalyzer::VisitStmt_(op));
1210	    auto root = GetRef<For>(op);
1211	
1212	    auto loop_layout = result_.for_map[root];
1213	
1214	    // Store the loop layout as an annotation on the For node (outermost)
1215	    auto for_ptr = for_node.CopyOnWrite();
1216	    for_ptr->annotations.Set(attr::kParallelLoopLayout, loop_layout);
1217	    if (result_.padding_guard_map.count(root)) {
1218	      for_ptr->annotations.Set(attr::kParallelLoopRequiresPaddingGuard,
1219	                               result_.padding_guard_map[root]);
1220	    }
1221	
1222	    // Store the predicate as an annotation if it exists and is not trivially
1223	    // true
1224	    if (result_.predicate_map.count(root)) {
1225	      PrimExpr predicate = analyzer_->Simplify(result_.predicate_map[root]);
1226	      // Only store predicate if it's not trivially true
1227	      if (!is_const_int(predicate, 1)) {
1228	        for_ptr->annotations.Set(attr::kParallelLoopPredicate, predicate);
1229	      }
1230	    }
1231	
1232	    return for_node;
1233	  }
1234	
1235	  Stmt VisitStmt_(const AttrStmtNode *op) final {
1236	    if (op->attr_key == tirx::attr::thread_extent) {
1237	      IterVar iv = Downcast<IterVar>(op->node);
1238	    }
1239	    return IRMutatorWithAnalyzer::VisitStmt_(op);
1240	  }
1241	
1242	private:
1243	  const LayoutInferenceResult result_;
1244	};
1245	
1246	tvm::transform::Pass LayoutInference() {
1247	  using namespace tirx::transform;
1248	  auto pass_func = [=](PrimFunc f, const IRModule &m, const PassContext &ctx) {
1249	    f = LayoutInferencer::Substitute(std::move(f));
1250	    // Validate parallel loop layout annotations
1251	    ParallelLoopLayoutValidator::Validate(f->body);
1252	    return f;
1253	  };
1254	  return CreatePrimFuncPass(pass_func, 0, "tl.LayoutInference", {});
1255	}
1256	
1257	TVM_FFI_STATIC_INIT_BLOCK() {
1258	  namespace refl = reflection;
1259	  refl::GlobalDef().def("tl.transform.LayoutInference", LayoutInference);
1260	}
1261	
1262	} // namespace tl
1263	} // namespace tvm
